#!/usr/bin/env python3
"""读取 CSV 文件，统计每一列的非空值数量。"""

import argparse
import csv
import sys


def count_nonempty(path):
    with open(path, newline="", encoding="utf-8-sig") as f:
        reader = csv.reader(f)
        try:
            header = next(reader)
        except StopIteration:
            return [], {}

        counts = {name: 0 for name in header}
        for i, row in enumerate(reader, start=2):
            for name, value in zip(header, row):
                if value.strip():
                    counts[name] += 1
            if len(row) > len(header):
                print(
                    f"警告: 第 {i} 行列数多于表头，额外列已忽略",
                    file=sys.stderr,
                )
        return header, counts


def main():
    parser = argparse.ArgumentParser(description="统计 CSV 每一列的非空值数量")
    parser.add_argument("csv_file", help="CSV 文件路径")
    args = parser.parse_args()

    try:
        header, counts = count_nonempty(args.csv_file)
    except FileNotFoundError:
        print(f"错误: 文件不存在: {args.csv_file}", file=sys.stderr)
        return 1

    if not header:
        print("错误: CSV 文件为空", file=sys.stderr)
        return 1

    width = max(len(h) for h in header)
    for name in header:
        print(f"{name:<{width}}  {counts[name]}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
